'use strict';

const assert = require('node:assert/strict');
const disableOperatorPreview = require('./solution');

assert.equal(typeof disableOperatorPreview, 'function');

const session = {
  id: 'session-1',
  operator: {
    previewEnabled: true,
    broadcastEnabled: true,
    name: 'operator'
  },
  viewers: [
    { id: 'v1', active: true },
    { id: 'v2', active: false }
  ]
};
const snapshot = JSON.stringify(session);
const result = disableOperatorPreview(session);

assert.notStrictEqual(result, session);
assert.notStrictEqual(result.operator, session.operator);
assert.notStrictEqual(result.viewers, session.viewers);
assert.notStrictEqual(result.viewers[0], session.viewers[0]);
assert.notStrictEqual(result.viewers[1], session.viewers[1]);
assert.deepEqual(result, {
  id: 'session-1',
  operator: {
    previewEnabled: false,
    broadcastEnabled: true,
    name: 'operator'
  },
  viewers: [
    { id: 'v1', active: true },
    { id: 'v2', active: false }
  ]
});
assert.equal(JSON.stringify(session), snapshot);

const alreadyDisabled = {
  operator: { previewEnabled: false, broadcastEnabled: false },
  viewers: []
};
const emptyResult = disableOperatorPreview(alreadyDisabled);
assert.deepEqual(emptyResult, alreadyDisabled);
assert.notStrictEqual(emptyResult, alreadyDisabled);
assert.notStrictEqual(emptyResult.operator, alreadyDisabled.operator);
assert.notStrictEqual(emptyResult.viewers, alreadyDisabled.viewers);

const frozen = Object.freeze({
  operator: Object.freeze({ previewEnabled: true, broadcastEnabled: false }),
  viewers: Object.freeze([Object.freeze({ id: 'viewer' })])
});
assert.doesNotThrow(() => disableOperatorPreview(frozen));

for (const invalid of [
  null, undefined, 3, {},
  { operator: null, viewers: [] },
  { operator: {}, viewers: [] },
  { operator: { previewEnabled: 'yes', broadcastEnabled: true }, viewers: [] },
  { operator: { previewEnabled: true, broadcastEnabled: 1 }, viewers: [] },
  { operator: { previewEnabled: true, broadcastEnabled: true }, viewers: null },
  { operator: { previewEnabled: true, broadcastEnabled: true }, viewers: [null] },
  { operator: { previewEnabled: true, broadcastEnabled: true }, viewers: [3] }
]) {
  assert.throws(() => disableOperatorPreview(invalid), TypeError);
}

